Algorithme MaxSousMatrice;
Var
    N, M, R1, C, MaxS : Entier;
    Mat[50][50] : Entier;
Debut
    Lire(N);
    Lire(M);
    Pour R1 <- 0 a N - 1 Faire
        Pour C <- 0 a M - 1 Faire
            Lire(Mat[R1][C]);
        FinPour;
    FinPour;

    // TODO: Trouver la somme maximale d'une sous-matrice et stocker dans MaxS



    Ecrire(MaxS);
Fin.
